import type { StudyQuestion } from "./study";

export const scenarioQuestions3: Record<string, StudyQuestion[]> = {
  "qlikview-12-data-architect": [
    { q: "A QlikView load script joins two tables that share an unintended second common field, creating a synthetic key that inflates the row count in the final data model.", o: ["Ignore the synthetic key; it has no effect", "Rename the unintentionally shared field with AS in one of the LOAD statements so only the intended key field remains common", "Delete one entire table", "Switch to CONCATENATE instead"], a: 1, e: "As in Qlik Sense, a synthetic key in QlikView arises from two or more shared fields between tables; renaming the accidental extra field removes the unintended second association, resolving the synthetic key.", t: "Scenario · Medium" },
    { q: "A nightly QlikView reload of a very large fact table from a database is taking too long as data volume grows year over year.", o: ["Add more document cache only", "Implement an incremental load pattern: extract only new/changed rows from source (e.g., via a modified-date filter) and concatenate with the previously stored QVD", "Switch to a full reload every hour instead", "Remove all WHERE clauses from the script"], a: 1, e: "Incremental load — extracting only new/changed source rows and appending to an existing QVD of historical data — is the standard QlikView pattern for scaling reloads on large, growing fact tables.", t: "Scenario · Medium" },
    { q: "A QlikView data model shows unexpected results because two fact tables were associated directly to each other instead of through a shared dimension, at different grains.", o: ["This is the correct, recommended design", "Redesign to a star schema where each fact table associates independently to shared conformed dimensions, avoiding a direct fact-to-fact association at mismatched grains", "Merge both fact tables regardless of grain", "Add a synthetic key to force the association"], a: 1, e: "Associating two fact tables directly, especially at different grains, produces incorrect or ambiguous aggregations. The standard fix is a star schema where each fact table relates independently to shared dimension tables.", t: "Scenario · Medium" },
    { q: "An optimized QVD load in QlikView suddenly becomes much slower after a developer adds a WHERE clause filtering on a non-key field during the QVD LOAD statement.", o: ["QVD performance is unaffected by WHERE clauses", "The WHERE clause on a non-indexed field breaks optimized load mode, forcing row-by-row processing; move the filter to a subsequent resident load instead", "This means the QVD file is corrupted", "Switch to loading from Excel instead"], a: 1, e: "Optimized QVD loads require no transformations or WHERE clauses on non-indexed fields in the QVD LOAD itself; adding one drops the load into much slower unoptimized mode. Filtering after an optimized load (via a resident load) preserves speed.", t: "Scenario · Medium" },
    { q: "A finance QlikView document must ensure a regional controller only ever sees rows for their assigned region, enforced even if they know how to edit selections or bookmarks.", o: ["Rely on default selections only", "Implement Section Access with a security table mapping NTNAME/usernames to allowed region values, enforcing reduction at data load time", "Password-protect the QVW file only", "Hide the region field from the layout"], a: 1, e: "Section Access enforces row-level security at the data layer during load, based on the authenticated user — this can't be bypassed via UI manipulation, unlike hiding fields or relying on default selections.", t: "Scenario · Hard" },
    { q: "A QlikView developer must resolve a circular reference introduced when a new lookup table was added, which QlikView is now flagging with a warning at reload.", o: ["Circular references can be safely ignored in QlikView", "Break the loop by renaming a field on one association or restructuring with a link table so there's a single unambiguous path between the tables", "Delete the newly added lookup table's data entirely", "Use Section Access to suppress the warning"], a: 1, e: "A circular reference must be resolved for predictable association behavior; renaming a field to remove a redundant link, or introducing a link table, are the standard fixes — identical logic to Qlik Sense since both share the associative engine.", t: "Scenario · Hard" },
    { q: "A script must add a 'Region' lookup column to a very large fact table based on Store ID without any risk of duplicating fact rows.", o: ["JOIN the region table directly onto the fact table", "Use a mapping table with Mapping LOAD and ApplyMap() to perform the lookup, since ApplyMap never changes the row count of the target table", "CONCATENATE the region table onto the fact table", "Load the fact table twice, once per region"], a: 1, e: "ApplyMap performs a pure key-based lookup and cannot duplicate rows, unlike a JOIN, which can multiply fact rows if the join key isn't unique on the joined-in table — the safer choice for adding a single derived field.", t: "Scenario · Hard" },
    { q: "A QlikView incremental load pattern only appends new rows from the source, but the business also needs deleted source records reflected in the historical QVD.", o: ["Incremental loads cannot represent deletions", "Extract the full set of current keys from source, compare against the QVD's stored keys, and remove/flag rows no longer present in addition to appending new/changed ones", "Ignore deletions as an edge case", "Do a full reload every night instead of incremental"], a: 1, e: "A pure append-only incremental load has no way to detect rows removed at the source; correctly handling deletions requires comparing current source keys against the QVD's keys and removing/flagging the ones no longer present.", t: "Scenario · Hard" },
    { q: "A QlikView document architect wants a script that stops (aborts) an automated reload task if a critical source table unexpectedly returns very few or zero rows, to avoid publishing incomplete data.", o: ["Let the reload always complete regardless of row counts", "Add a script check using NoOfRows() after loading the critical table, and use an Exit Script / error condition if the count is below an expected threshold", "Manually inspect the document each morning", "Disable the scheduled task permanently"], a: 1, e: "Checking NoOfRows() after a critical load step and conditionally aborting (Exit Script) if the count is implausibly low is standard defensive scripting to prevent silently publishing an app built on a failed source extract.", t: "Scenario · Hard" },
    { q: "A large multi-fact QlikView model built with a link table needs the link table's composite key to be both unique and memory-efficient across three fact tables' shared dimensions.", o: ["Use raw concatenated text keys with no optimization", "Use AutoNumber() on the concatenation of the relevant dimension keys when building the link table, producing a compact integer key", "Create a separate composite key for each fact table pairing", "Avoid link tables and associate all facts directly to each other instead"], a: 1, e: "AutoNumber() converts a composite string key into an efficient integer representation, which is the standard technique for building compact, high-performance link-table keys in multi-fact QlikView models.", t: "Scenario · Hard" },
    { q: "A QlikView script needs to bring in only records modified since the last successful reload, using a ModifiedDate column, without risking missed records modified right at the reload boundary.", o: ["Filter strictly WHERE ModifiedDate > last_reload_time with no buffer", "Use a slightly overlapping window (WHERE ModifiedDate >= last_reload_time - buffer) plus a dedup/replace step keyed on the primary key, avoiding missed boundary records", "Reload weekly instead to sidestep the issue", "Ignore the boundary condition since it's rare"], a: 1, e: "A strict greater-than filter risks missing rows modified at the same instant as the prior extraction; an overlapping buffer window with deduplication on the key is the standard defensive incremental-load pattern.", t: "Scenario · Medium" },
    { q: "A data architect must validate immediately after loading a critical QlikView table that a key field has no NULL values, before the rest of the script proceeds.", o: ["Trust the source implicitly with no checks", "Add inline validation (e.g., counting IsNull() occurrences) right after the load and conditionally trigger an Exit Script/error if any unexpected NULLs are found", "Only check manually after publishing", "Drop the key field if it might contain nulls"], a: 1, e: "Defensive load-script validation immediately after loading a critical table — checking for unexpected NULLs in a key field and aborting if found — prevents building a downstream model on bad data, a core data-architect discipline.", t: "Scenario · Medium" },
    { q: "Two source systems feed a QlikView model with differently cased and whitespace-padded versions of what should be the same customer key, breaking associations.", o: ["Assume the associative engine normalizes this automatically", "Standardize the key during load using Upper()/Trim() (or build a cleaner surrogate key) applied consistently across both sources before association", "Leave as-is and cross-reference manually", "Merge the source databases physically first"], a: 1, e: "Qlik association requires exact field-value matches; normalizing keys with Trim()/Upper() during load (or building a consistent surrogate key) fixes mismatches caused by casing or whitespace differences between source systems.", t: "Scenario · Medium" },
    { q: "A shared QVD used by multiple QlikView documents must be produced by a single staging script so downstream documents don't each re-extract from the original source.", o: ["Each downstream document independently queries the original source", "Build a shared staging/ETL script that extracts from source once and writes a QVD, with downstream documents doing an optimized load from that shared QVD", "Copy the extraction script into every downstream document", "Merge all documents into one monolithic QlikView file"], a: 1, e: "A shared staging layer — extract once to QVD, then have multiple documents optimized-load from it — is a core Qlik data-architecture pattern that avoids redundant extraction and ensures consistency across consuming documents.", t: "Scenario · Hard" },
    { q: "A very large QVD load unexpectedly runs unoptimized even though the script has no WHERE clause on the QVD LOAD line.", o: ["Optimized mode has no other requirements beyond avoiding WHERE clauses", "Check for other subtle causes such as renaming fields with AS or an implicit type conversion in the field list, and keep the LOAD as a straightforward field list matching the QVD's own field names", "This always means the QVD file is corrupted", "Add more RAM as the only fix"], a: 1, e: "Beyond WHERE clauses, certain script constructs like renaming fields or transformations even within the field list can silently break optimized QVD load mode — a data architect needs to recognize these subtler causes, not just the WHERE-clause case.", t: "Scenario · Hard" },
    { q: "A Section Access table needs to let one 'admin' NTNAME see all data (bypass reduction) while all other users are reduced to their own region.", o: ["Section Access cannot support an unrestricted admin exception", "Add a row for the admin user with a wildcard '*' value in the reduction field, which Qlik treats as matching all values for that field", "Duplicate the QVW without Section Access just for the admin", "Give the admin a separate login with no Section Access table"], a: 1, e: "A wildcard ('*') value in a Section Access reduction field matches all values for that field, so an admin row using '*' for region achieves an unrestricted exception within the same reduction table used for everyone else.", t: "Scenario · Hard" },
    { q: "A QlikView model must let a single fact table be sliced by both a standard calendar and a fiscal calendar (starting in a different month) without duplicating the fact table.", o: ["Duplicate the fact table twice, once per calendar", "Build a date dimension carrying both standard and fiscal calendar attributes (or two calendar dimensions keyed on the same date field), so one fact table can be sliced by either", "Support only one calendar type per document", "Convert all fact dates to fiscal dates only"], a: 1, e: "A single date dimension carrying both standard and fiscal attributes (or two calendar tables linked via the same date key) lets one fact table be sliced by either calendar without duplicating the underlying fact data.", t: "Scenario · Hard" },
    { q: "A newly onboarded source delivers timestamps in a different timezone than the rest of a QlikView model, misaligning daily aggregates near midnight boundaries.", o: ["Timezones never affect QlikView data models", "Convert incoming timestamps to a single standard timezone during load before deriving the date key used for aggregation", "Ignore the offset since it's only a few hours", "Force all other sources to change their timezone instead"], a: 1, e: "Timezone inconsistencies across sources should be normalized to a single standard during load before deriving date keys, otherwise date-based aggregations near midnight boundaries will misalign between sources.", t: "Scenario · Hard" },
    { q: "A QlikView reload task chains several documents (Document A produces a QVD that Document B consumes), and B occasionally runs against a stale QVD because task scheduling isn't coordinated.", o: ["Schedule both tasks independently at similar times and hope for the best", "Chain the tasks explicitly (trigger B to run only after A completes successfully, e.g., via the Task Scheduler's 'On success of another task' trigger)", "Merge both documents into one to avoid the dependency", "Manually run B by hand after checking A finished"], a: 1, e: "QlikView's task scheduler supports explicit task chaining (triggering a downstream task only on successful completion of an upstream one), which removes the timing guesswork of independently scheduled tasks and guarantees B always reads a fresh QVD from A.", t: "Scenario · Hard" },
    { q: "A QlikView document is shared by multiple downstream reports/documents, and a planned field rename in the source QVD would silently break every document that references the old field name.", o: ["Rename freely since QlikView documents auto-adapt to upstream renames", "Treat the shared QVD's schema as a contract: coordinate the rename with all consuming document owners, or keep the old field name as an alias during a transition period, before applying the change", "Delete and rebuild every downstream document after the rename", "Let each downstream document owner discover the break on their own"], a: 1, e: "A shared QVD used by multiple documents functions as a data contract; renaming a field without coordinating with downstream consumers (or providing a transition alias) silently breaks every document that references the old name — a real data-architecture governance concern.", t: "Scenario · Medium" },
  ],
  "qlikview-12-business-analyst": [
    { q: "An analyst needs a chart object where one expression always shows total company revenue regardless of the user's current region/product selections, alongside a second expression that responds to selections.", o: ["Sum(Revenue) for both expressions", "Sum({1} Revenue) for the fixed total (ignoring selections) alongside Sum(Revenue) for the selection-driven expression", "Only one expression is possible per chart", "Use a separate document for the fixed total"], a: 1, e: "The {1} set analysis operator represents the entire dataset ignoring current selections, letting one expression act as a fixed benchmark while a plain Sum(Revenue) expression in the same chart still reflects live selections.", t: "Scenario · Medium" },
    { q: "A user selects a specific product and notices some customers turn gray in a customer list box, while others stay white. What does this indicate?", o: ["The app has a data error", "Gray values are excluded — no association exists between the selected product and those customers in the data — while white values remain possible given the current selection; this is the associative engine functioning correctly", "Gray means 'selected' and white means 'excluded'", "This only happens when Section Access is misconfigured"], a: 1, e: "In QlikView's associative model, gray indicates excluded values (no logical association with the current selection) and white indicates possible values — this is expected behavior showing real data relationships, not an error.", t: "Scenario · Medium" },
    { q: "A business analyst wants to display 'this year' and 'last year' revenue side-by-side as two bars per category, without requiring the user to change any selections.", o: ["Build two separate documents, one per year", "Use two measure expressions with set analysis, e.g. Sum({<Year={$(=Max(Year))}>} Revenue) and Sum({<Year={$(=Max(Year)-1)}>} Revenue)", "Only show the latest year", "Ask users to manually toggle selections between charts"], a: 1, e: "Dynamic set analysis with variables (like $(=Max(Year))) lets each expression pin to a specific year independent of the user's actual field selections, enabling a clean side-by-side year comparison in the same chart.", t: "Scenario · Medium" },
    { q: "A KPI text object needs to always reflect the currently filtered sales total and update immediately as users click through selections in list boxes.", o: ["A static value typed into a text box", "An expression like Sum(Sales) inside the text object, since QlikView recalculates expressions live based on current selections", "A value calculated once at reload time only", "This requires a macro to refresh manually"], a: 1, e: "QlikView expressions recalculate automatically and immediately as selections change across the document — no macro or manual refresh is required for a standard Sum(Sales)-style expression to reflect the live filtered state.", t: "Scenario · Medium" },
    { q: "An analyst wants a bar chart to show only the top 5 customers by revenue, with the ranking correctly updating as the user filters by region.", o: ["Hardcode the 5 customer names in the load script", "Apply a dimension limit ('Show only Top 5 by expression: Sum(Revenue)') on the Customer dimension so it recalculates dynamically as selections change", "Manually delete rows below rank 5 after each reload", "Filter to 5 arbitrary customers at the script level"], a: 1, e: "QlikView's dimension limits ('Show only... Top N by expression') dynamically recompute the top N based on live expression values and the current selection context, correctly re-ranking as filters like region change.", t: "Scenario · Hard" },
    { q: "A chart expression Sum({<Year={2025}>} Revenue) no longer responds when the business changes its 'current year' via a variable that used to drive this, because someone hardcoded the year value.", o: ["Set analysis cannot reference variables in QlikView", "Replace the hardcoded literal with the variable, e.g. Sum({<Year={$(vCurrentYear)}>} Revenue), restoring dynamic behavior tied to the variable's value", "Remove the set analysis and just use Sum(Revenue)", "Convert the variable into a new dimension"], a: 1, e: "QlikView set analysis fully supports variable references via $(variableName) syntax; a hardcoded literal breaks that dynamism, so substituting the variable restores the intended flexible behavior.", t: "Scenario · Hard" },
    { q: "An analyst needs each product's percentage contribution to its own category's total revenue, correctly recalculating at whatever selection level a user applies.", o: ["Sum(Revenue) divided by a manually typed constant", "Sum(Revenue) / Sum(Total <Category> Revenue), using Total qualified by Category to compute the category-level denominator dynamically", "Sum(Revenue) / Sum(Total Revenue) without qualifying by Category", "A hardcoded percentage per product entered manually"], a: 1, e: "Sum(Total <Category> Revenue) computes the category-level total independent of the chart's row-level product dimension, giving the correct dynamic 'percent of category' pattern that still respects the user's live selections.", t: "Scenario · Hard" },
    { q: "A dashboard should show the count of unique customers who purchased within the current selection, not the number of individual order line-items.", o: ["Count(OrderLine)", "Count(Distinct CustomerID)", "Sum(CustomerID)", "Count(CustomerID) without DISTINCT gives the same result"], a: 1, e: "Count(Distinct CustomerID) counts unique customers, correctly avoiding overcounting when a customer has multiple order lines — a plain Count(CustomerID) or Count(OrderLine) would count every row, not every unique customer.", t: "Scenario · Hard" },
    { q: "An analyst wants to compare two independently selected customer segments side-by-side on the same chart, where each segment can have its own separate selections applied.", o: ["This requires two entirely separate QlikView documents", "Use alternate states: define two states, let users make independent selections in each, and reference each state in the relevant expressions (e.g., Sum({StateA} Revenue) vs Sum({StateB} Revenue))", "Switch back and forth manually using bookmarks each time", "Alternate states are a Qlik Sense-only feature"], a: 1, e: "QlikView also supports alternate states, allowing independent selection contexts within the same document; referencing each named state in an expression is exactly how side-by-side comparison visuals like this are built.", t: "Scenario · Hard" },
    { q: "A long-tail product list clutters a bar chart with dozens of tiny bars for low-volume SKUs, and the analyst wants to consolidate them into a single 'Other' category without deleting underlying data.", o: ["Delete the low-volume SKUs from the source data", "Use a calculated dimension (an If/Aggr-based bucketing expression, or a grouping) that maps long-tail SKUs into an 'Other' bucket for display purposes only", "Sort the chart differently and accept the clutter", "Filter out low-volume SKUs from the whole document"], a: 1, e: "A calculated dimension that buckets small values into 'Other' declutters the visualization while keeping the full underlying data intact and available elsewhere in the document, rather than permanently removing it.", t: "Scenario · Hard" },
    { q: "An analyst needs a bookmark that captures the current selections in a QlikView document so a specific view can be reopened later exactly as configured.", o: ["Take a screenshot instead", "Create a Bookmark, which stores the current selection state so it can be reapplied later", "Manually document which fields were selected in a text file", "Rebuild the selections from memory each time"], a: 1, e: "QlikView Bookmarks capture the exact selection state at a point in time, letting a user instantly reapply it later — the built-in mechanism for preserving and reusing a specific analytical view.", t: "Scenario · Medium" },
    { q: "An analyst needs a measure showing revenue excluding a specific promotional category, without permanently filtering that category out of the whole document.", o: ["Permanently remove the category from the data model", "Use set analysis to exclude the category within the expression itself, e.g. Sum({<Category-={'Promo'}>} Revenue), leaving the rest of the document's selections and data intact", "Ask users to manually deselect the category every time", "Build a separate document without the promo category"], a: 1, e: "Set analysis modifiers like Category-={'Promo'} exclude specific values from just that one expression's calculation without altering the underlying data model, ideal for a single measure-level exclusion.", t: "Scenario · Medium" },
    { q: "A chart needs to highlight, via color, whether each region's revenue is above or below the company average, updating dynamically as selections change.", o: ["Hardcode fixed colors per region", "Use color-by-expression comparing each region's value to Avg(Total <Region> Revenue) or the overall average, changing color dynamically based on that comparison", "Sort by color manually after each refresh", "Use a single color for all regions"], a: 1, e: "QlikView's expression-driven color capability lets a chart's colors reflect a dynamic condition (comparing a region to the live company average), so highlighting above/below-average performance updates automatically with selections.", t: "Scenario · Medium" },
    { q: "A business analyst needs a single measure showing the arithmetic difference between this period's and the prior period's revenue (not a ratio), for a variance card.", o: ["Sum(Revenue) alone", "Sum({<Period={$(=Max(Period))}>} Revenue) - Sum({<Period={$(=Max(Period)-1)}>} Revenue), computing the difference between two set-analysis-scoped expressions", "Divide this period by last period", "A calculated dimension instead of a measure"], a: 1, e: "Subtracting two set-analysis-scoped expressions (this period vs. prior period, each pinned via dynamic variables) gives the absolute variance needed for a difference-based KPI, distinct from a percentage/ratio comparison.", t: "Scenario · Medium" },
    { q: "An analyst's straight table needs a subtotal row per region showing the sum of that region's products, alongside individual product rows.", o: ["This requires a separate chart per region", "Enable subtotals in the pivot/straight table's presentation settings, which automatically computes and displays a subtotal row per dimension group like region", "Manually calculate and type in each region's subtotal", "Use a single-value gauge object instead"], a: 1, e: "QlikView pivot tables (and straight tables with subtotal options) can automatically compute and display grouped subtotal rows per dimension value without manual calculation.", t: "Scenario · Medium" },
    { q: "A dashboard needs a measure showing the number of days since a customer's last purchase, to flag customers at risk of churn.", o: ["Count(Orders)", "Today() - Max(OrderDate), computed per customer (e.g., via an Aggr-based or dimension-level expression), giving days since last purchase", "Sum(OrderDate)", "A static value entered manually per customer"], a: 1, e: "Subtracting a customer's most recent order date from today's date (evaluated per customer) gives a recency metric commonly used to flag churn risk — a standard analyst-level calculation.", t: "Scenario · Hard" },
    { q: "An analyst needs a KPI showing what percentage of total selected revenue comes from the top 3 customers, to illustrate customer concentration risk.", o: ["This cannot be calculated with QlikView expressions", "Sum of the top-3 customers' revenue (via Rank() or a Top-N set analysis condition) divided by Sum(Revenue) for the full current selection, expressed as a percentage", "Manually identify and hardcode the top 3 permanently", "Count(Distinct CustomerID) instead"], a: 1, e: "Combining a Rank()-based or Top-N set analysis numerator (top 3 customers) with the overall Sum(Revenue) as denominator produces a dynamic concentration-risk percentage that updates with selections — a more advanced set analysis pattern.", t: "Scenario · Hard" },
    { q: "A sheet's chart shows changed results after a user selects a field that has no direct association with the charted dimension, and the analyst must explain why.", o: ["Selections only ever affect directly associated fields, so this shouldn't happen", "Explain that QlikView's associative model propagates selections through the entire connected data model via any chain of associated tables, not just directly linked fields", "This indicates a corrupted data model", "Numbers changing is always a bug"], a: 1, e: "QlikView's associative engine propagates a selection's effect across the whole connected model through chains of association — so a selection in a seemingly unrelated field can still legitimately affect an aggregation elsewhere via an indirect association path.", t: "Scenario · Hard" },
    { q: "An analyst wants a single object to switch between showing 'Revenue' or 'Margin' based on a variable-controlled input, without duplicating the chart.", o: ["Build two separate chart objects and hide/show manually", "Use a variable-driven expression (an input field or list box tied to a variable, referenced in the chart's expression, e.g. $(vSelectedMeasure)) so the same object dynamically switches its calculation", "This requires a separate document per measure", "Only one measure can ever be shown per document"], a: 1, e: "Binding a chart expression to a variable that an input control sets lets a single object dynamically switch what it calculates (Revenue vs Margin) based on user choice, avoiding duplicate objects for each possible metric.", t: "Scenario · Hard" },
    { q: "A business analyst needs a measure comparing 'yesterday' against the 'same weekday last week' rather than the calendar day before, to account for weekly seasonality (e.g., comparing a Monday to the prior Monday).", o: ["Sum({<Date={$(=Today()-1)}>} Revenue) is always sufficient for this comparison", "Sum({<Date={$(=Today()-7)}>} Revenue) compared against Sum({<Date={$(=Today()-1)}>} Revenue), explicitly using a 7-day offset for the weekday-matched comparison rather than a simple prior-day offset", "Compare against the monthly average instead", "This comparison isn't possible in set analysis"], a: 1, e: "To compare against the same weekday in the prior week and account for weekly seasonality, the set analysis expression must use a 7-day offset rather than a simple 1-day offset, which would instead compare against a potentially different weekday.", t: "Scenario · Hard" },
  ],
  "databricks-machine-learning-associate": [
    { q: "A data scientist trains several model variants and needs to compare their metrics (accuracy, F1) and parameters side-by-side before choosing which to promote.", o: ["Keep notes in a separate spreadsheet manually", "Log each run's parameters and metrics with MLflow Tracking, then compare runs in the MLflow UI/experiment view", "Overwrite the same model file repeatedly", "Only keep the final model with no history"], a: 1, e: "MLflow Tracking is designed exactly for this: logging parameters, metrics, and artifacts per run so multiple model variants can be compared side-by-side in the tracking UI before a promotion decision is made.", t: "Scenario · Medium" },
    { q: "A team wants to quickly establish a baseline model on a new tabular dataset before investing in custom feature engineering and hyperparameter tuning.", o: ["Manually try dozens of algorithms by hand", "Use Databricks AutoML to automatically generate baseline models, complete with generated source notebooks for the best trials", "Skip baselining and go straight to deep learning", "Only use a rules-based heuristic forever"], a: 1, e: "AutoML on Databricks automatically trains and tunes a set of candidate models on tabular data, producing a leaderboard and editable generated notebooks — an efficient way to establish a solid baseline before custom work.", t: "Scenario · Medium" },
    { q: "Multiple team members are engineering similar features (e.g., customer lifetime value) independently for different models, causing inconsistency and duplicated effort.", o: ["Let each team keep duplicating feature logic", "Use Feature Store to compute and register the feature once, allowing multiple models/teams to look it up consistently at training and inference time", "Store the feature only in each model's own notebook", "Recompute it manually before every model run"], a: 1, e: "Feature Store centralizes feature computation and definitions so they can be reused consistently across teams and models, avoiding duplicated logic and reducing training/serving skew — precisely the problem described.", t: "Scenario · Medium" },
    { q: "A model trained on a small pandas DataFrame needs to be retrained on a dataset that no longer fits in a single machine's memory.", o: ["Keep using pandas and hope it works", "Use a distributed approach: Spark MLlib for a Spark-native algorithm, or distribute a single-node library via a distributor API for larger-than-memory training", "Downsample the data until it's tiny, permanently", "Switch to a smaller model type only"], a: 1, e: "When data no longer fits on one machine, Databricks offers Spark MLlib for natively distributed training, or ways to distribute single-node libraries across the cluster — rather than permanently discarding data via downsampling or hoping pandas scales.", t: "Scenario · Medium" },
    { q: "A registered model in the Model Registry needs to move from 'Staging' to 'Production' only after a manual review confirms it outperforms the current production model on a held-out test set.", o: ["Auto-promote every new model immediately", "Use MLflow Model Registry stage transitions, evaluating against the current production model's metrics before manually (or via an approval step) transitioning the model version to Production", "Retrain the model repeatedly until it's perfect", "Skip the registry and deploy from a notebook directly"], a: 1, e: "The Model Registry's stage transitions (None/Staging/Production/Archived) support a governed promotion workflow, where a version is only moved to Production after the required validation/comparison and approval — exactly the controlled process described.", t: "Scenario · Medium" },
    { q: "A model performs well on training data but noticeably worse on validation data, and the gap widens as more features are added.", o: ["This means the validation set is wrong", "This is a sign of overfitting; consider regularization, feature selection/reduction, more training data, or simpler models to reduce the train/validation gap", "Add even more features to fix it", "Increase the number of training epochs with no other changes"], a: 1, e: "A growing gap between training and validation performance as complexity increases is a classic overfitting signature; regularization, reducing/selecting features, gathering more data, or a simpler model are the standard mitigations.", t: "Scenario · Hard" },
    { q: "A hyperparameter search for a gradient-boosted tree model needs to efficiently explore a large search space across a Spark cluster rather than sequentially on one node.", o: ["A manual for-loop trying combinations one at a time", "Hyperopt with SparkTrials, distributing hyperparameter trials across the cluster in parallel while tracking each trial in MLflow", "Grid search only on the driver node", "Skip tuning and use default hyperparameters"], a: 1, e: "Hyperopt combined with SparkTrials distributes the evaluation of different hyperparameter combinations across the Spark cluster's executors in parallel, which is far more efficient than sequential search on a single node, and integrates with MLflow tracking.", t: "Scenario · Hard" },
    { q: "A binary classification model for fraud detection has 99% accuracy, but the business complains it misses most actual fraud cases. What does this reveal about the metric choice?", o: ["99% accuracy always means the model is excellent", "With a highly imbalanced class distribution (fraud is rare), accuracy is misleading; metrics like precision, recall, F1, or AUC-PR that account for the minority class are more appropriate", "The model must be retrained with more epochs only", "Accuracy issues can only be fixed by collecting more data"], a: 1, e: "On imbalanced datasets (fraud being rare), a model can achieve high accuracy simply by predicting the majority class most of the time while missing almost all true positives; recall, F1, or AUC-PR better reflect performance on the minority class that actually matters.", t: "Scenario · Hard" },
    { q: "A trained model's feature set at inference time in production doesn't perfectly match what it saw during training due to upstream schema drift, risking silent prediction errors.", o: ["This cannot be detected or prevented", "Use Feature Store's feature lookup with defined schemas/versions (and/or model signature validation in MLflow) to catch schema mismatches between training and serving", "Ignore the mismatch since models are robust to any input", "Retrain from scratch every day regardless of drift"], a: 1, e: "MLflow model signatures validate that inference-time inputs match the schema seen during training, and Feature Store's versioned feature definitions help keep training and serving feature sets consistent — both are designed to catch this kind of drift early rather than fail silently.", t: "Scenario · Hard" },
    { q: "A cross-validation setup on time-series data using standard random k-fold splits produces unrealistically optimistic performance estimates in backtesting.", o: ["Random k-fold is always appropriate regardless of data type", "Use a time-series-aware split (e.g., forward-chaining/rolling-origin cross-validation) so the model is never validated on data that precedes its training window", "Increase k to fix the issue", "Shuffle the data more aggressively before splitting"], a: 1, e: "Random k-fold splitting can leak future information into training folds for time-series data, inflating validation performance unrealistically; time-aware splits (forward-chaining, where validation always follows training in time) give a realistic estimate of real-world performance.", t: "Scenario · Hard" },
    { q: "A dataset has a categorical feature with hundreds of distinct values (e.g., zip code), and one-hot encoding it would explode the feature space and hurt tree-based model performance.", o: ["One-hot encode it regardless of cardinality", "Consider target/frequency encoding, hashing, or grouping rare categories, which handle high-cardinality categorical features more efficiently than naive one-hot encoding", "Drop the feature entirely without investigation", "Convert the categories to random integers with no ordering meaning"], a: 1, e: "High-cardinality categorical features are better handled with encodings like target encoding, frequency encoding, hashing, or grouping rare levels together, rather than exploding the dimensionality via naive one-hot encoding, which also tends to hurt tree-based models.", t: "Scenario · Medium" },
    { q: "A dataset has a small percentage of missing values in a numeric feature, and a data scientist must choose an imputation approach that doesn't bias a downstream linear model.", o: ["Drop every row with any missing value regardless of how much data is lost", "Consider mean/median imputation (or a model-based imputation) combined with an added 'was missing' indicator flag, so the model can still learn from and account for missingness patterns", "Replace missing values with zero unconditionally regardless of feature scale", "Ignore the missing values; most libraries handle them automatically for any model type"], a: 1, e: "Simple imputation (mean/median) paired with a missing-indicator flag preserves information about which rows had missing data (which can itself be predictive) while giving linear models complete numeric input, rather than discarding rows or using an arbitrary constant that could bias results.", t: "Scenario · Medium" },
    { q: "A model's feature importance ranking (from a tree-based model) shows two highly correlated features splitting the importance between them, making it look like neither matters much individually.", o: ["This means both features are useless and should be removed", "Recognize that correlated features can dilute each other's apparent importance in tree-based splits; consider examining combined importance, using permutation importance, or removing one of the redundant features to clarify the signal", "Always trust the raw importance ranking at face value with no further investigation", "Increase the number of trees to fix this automatically"], a: 1, e: "Correlated features can arbitrarily split attributed importance between them in tree ensembles even when the combined signal is strong; combined/permutation importance analysis or removing redundancy clarifies the true predictive value, rather than concluding the features are unimportant from the raw split alone.", t: "Scenario · Medium" },
    { q: "A binary classifier's default 0.5 probability threshold produces too many false positives for a business use case where false positives are costly (e.g., flagging valid transactions as fraud).", o: ["The threshold cannot be changed; only the model can be retrained", "Adjust the classification threshold higher than 0.5 (informed by the precision-recall tradeoff or a cost-based analysis) to reduce false positives at the cost of some recall", "Always keep 0.5 as a universal standard regardless of business cost asymmetry", "Only accuracy should be used to make this decision"], a: 1, e: "The classification threshold is a tunable decision boundary independent of retraining; raising it above 0.5 trades some recall for higher precision, which is appropriate when false positives carry a higher business cost than false negatives, informed by a precision-recall or cost-based analysis.", t: "Scenario · Medium" },
    { q: "A model registered in MLflow's registry needs its predictions periodically compared against ground truth once labels become available weeks later, to catch gradual accuracy decay.", o: ["Assume a model deployed once stays accurate indefinitely", "Set up a recurring evaluation job that joins delayed ground-truth labels back to logged predictions and computes accuracy/quality metrics over time, alerting on significant decay", "Only evaluate the model once, before initial deployment", "Wait for user complaints before checking model performance"], a: 1, e: "Since labels arrive late, a recurring job that joins them back to previously logged predictions (via an inference table or similar logging) and tracks quality metrics over time is the standard way to catch gradual accuracy decay in production, rather than assuming static performance or waiting for complaints.", t: "Scenario · Hard" },
    { q: "A model needs to run inference on millions of rows overnight as a batch job, rather than being queried one row at a time via a real-time endpoint.", o: ["Stand up a real-time serving endpoint and call it millions of times sequentially", "Use a batch inference approach — loading the registered model (e.g., via MLflow's pyfunc) and applying it with Spark across the dataset in parallel as a scheduled job", "Manually score rows one at a time in a spreadsheet", "Convert the entire dataset into a real-time streaming source unnecessarily"], a: 1, e: "For large offline scoring needs, loading a registered MLflow model and applying it via a Spark UDF or batch inference API in a scheduled job is far more efficient and appropriate than hammering a real-time serving endpoint row by row.", t: "Scenario · Hard" },
    { q: "A model's training pipeline must be fully reproducible such that re-running it with the same inputs produces the same model, but results vary slightly between runs due to non-deterministic elements.", o: ["Accept that ML training can never be reproducible", "Set explicit random seeds across all relevant libraries (numpy, the ML framework, data shuffling) and pin data/library versions, since most 'randomness' in training is actually controllable via seeding and environment pinning", "Only fix this by using a different algorithm", "Ignore reproducibility since MLflow tracks metrics anyway"], a: 1, e: "Most apparent non-determinism in ML training comes from unseeded random number generators (data shuffling, weight initialization) and unpinned library/environment versions; explicitly setting seeds and pinning versions makes training runs reproducible, which MLflow tracking alone does not guarantee.", t: "Scenario · Hard" },
    { q: "A feature engineering pipeline computes a feature using a rolling window over time, and a data scientist must ensure this doesn't leak future information into a row's training features.", o: ["Any rolling window feature is automatically leak-free", "Ensure the rolling window for a given row's timestamp only includes data strictly prior to (or up to) that timestamp, never data from after it, since including future data in a feature causes target leakage", "Use the entire dataset's mean for every row instead", "Ignore timestamp ordering when computing rolling features"], a: 1, e: "A rolling/window feature must be computed using only data available up to (not after) each row's timestamp; including future values in that row's feature constitutes target/temporal leakage, which inflates offline metrics but fails in real production use where future data isn't available.", t: "Scenario · Hard" },
    { q: "A team wants to compare a champion model's real business impact (e.g., revenue lift) against a challenger model, not just offline accuracy metrics, before fully promoting the challenger.", o: ["Offline accuracy is always sufficient evidence for promotion decisions", "Run an online A/B test routing live traffic between champion and challenger, measuring the actual business metric (e.g., revenue, conversion) rather than relying solely on offline evaluation metrics", "Only ask the data science team for their opinion", "Promote based on whichever model trained faster"], a: 1, e: "Offline metrics don't always translate directly into real business impact; an online A/B test comparing champion and challenger on live traffic against the actual business KPI is the rigorous way to validate a promotion decision at the Professional level.", t: "Scenario · Hard" },
    { q: "A model that performed well in offline testing shows a sharp performance drop specifically for a new customer segment introduced after the model was trained, while overall aggregate metrics still look acceptable.", o: ["Aggregate metrics looking fine means there's nothing to investigate", "Slice model performance by relevant segments (including new/emerging ones) rather than relying solely on the aggregate metric, since a new segment underrepresented in training data can perform poorly while barely moving the overall average", "Retrain immediately without first diagnosing which segment is affected", "Assume this is normal variance and take no action"], a: 1, e: "Aggregate metrics can mask segment-specific degradation, especially for a new or underrepresented group; slicing evaluation by segment is necessary to catch cases where a model performs poorly for a specific population even while the overall average still looks acceptable.", t: "Scenario · Medium" },
  ],
  "databricks-machine-learning-professional": [
    { q: "A production model's champion/challenger evaluation must run automatically whenever a new candidate is registered, comparing it against the current production model on the same held-out dataset before any promotion.", o: ["Manually run notebooks whenever someone remembers", "Build an automated MLflow-based workflow/job that evaluates the challenger against the champion on the same metrics/dataset and gates the Model Registry stage transition on the result", "Always promote the newest model automatically with no comparison", "Skip evaluation and rely on production monitoring alone"], a: 1, e: "Professional-level MLOps practice automates champion/challenger evaluation as part of the registry promotion workflow, so a candidate model only advances (e.g., to Production) after objectively outperforming the current champion on a consistent evaluation set — not by manual habit or blind promotion.", t: "Scenario · Medium" },
    { q: "A model serving endpoint needs to log every prediction request/response for later drift analysis, without adding significant latency to the live serving path.", o: ["Synchronously write every request to a database before responding", "Use Databricks Model Serving's built-in inference table logging (or asynchronous logging) to capture requests/responses for downstream drift analysis without blocking the response", "Skip logging to keep latency low", "Log only 1% of traffic and call it sufficient forever"], a: 1, e: "Databricks Model Serving supports inference tables that automatically and asynchronously log requests and responses for later analysis, avoiding the latency penalty of synchronous logging in the request path while still capturing full data for drift monitoring.", t: "Scenario · Medium" },
    { q: "A team needs advanced feature governance: tracking which model versions consumed which feature table versions, for full lineage and reproducibility during an audit.", o: ["Feature lineage cannot be tracked in Databricks", "Use Feature Store's lineage tracking, which records which features (and their versions) were used to train each registered model version", "Manually maintain a spreadsheet of feature usage", "Only track lineage for the most recent model version"], a: 1, e: "Feature Store automatically tracks lineage between feature tables and the models trained from them, recording which feature versions fed which model versions — exactly what's needed for audit-grade reproducibility at the Professional level.", t: "Scenario · Medium" },
    { q: "A deployed model's prediction distribution has begun to shift over several weeks compared to its training distribution, though no errors are occurring and accuracy hasn't been directly measurable yet (labels arrive late).", o: ["Wait for labels and do nothing until then", "Implement proactive drift monitoring on input features and/or prediction distributions (e.g., via Lakehouse Monitoring) to catch data/concept drift before delayed labels confirm a real accuracy problem", "Assume the model is fine since no errors are thrown", "Retrain on a fixed schedule with no drift signal considered"], a: 1, e: "When ground-truth labels are delayed, monitoring input feature and prediction distributions for drift is the standard proactive signal that something may be changing, allowing intervention before delayed labels eventually confirm degraded accuracy.", t: "Scenario · Hard" },
    { q: "A canary deployment strategy is needed for a new model version, routing only 5% of production traffic to it initially while monitoring business metrics before a full rollout.", o: ["Immediately switch 100% of traffic to the new version", "Configure traffic splitting on the serving endpoint (e.g., 95%/5% between champion and challenger) and monitor business/quality metrics before gradually increasing the new version's share", "Deploy the new model to a separate, unrelated endpoint with no comparison", "Only test in a notebook and skip live canarying"], a: 1, e: "Traffic splitting on a serving endpoint enables canary deployments: a small percentage of real traffic is routed to the new version while metrics are compared against the champion, allowing safe, gradual rollout rather than an all-at-once switch.", t: "Scenario · Hard" },
    { q: "A regulated industry requires that every production model prediction can be traced back to the exact code, data version, and hyperparameters used to train that model, months later.", o: ["This level of traceability isn't achievable with MLflow", "Ensure MLflow Tracking logs the code version (git commit), data version (e.g., Delta table version via time travel), and parameters for every run tied to the registered model version, satisfying full reproducibility", "Keep only the final model file with no metadata", "Manually document this in an external wiki inconsistently"], a: 1, e: "MLflow Tracking, combined with Delta Lake's data versioning, can capture the full lineage (code commit, data version, hyperparameters, metrics) needed for regulatory-grade reproducibility, tied directly to each registered model version.", t: "Scenario · Hard" },
    { q: "An advanced hyperparameter tuning job must dynamically stop clearly underperforming trials early to save cluster compute, rather than letting every trial run to completion.", o: ["Run all trials to full completion regardless of intermediate results", "Use early stopping logic in the tuning framework (e.g., Hyperopt with early_stop_fn, or a pruning-aware framework) so unpromising trials are terminated early based on intermediate metrics", "Reduce the search space to only 2 combinations", "Increase cluster size to brute-force through all trials faster"], a: 1, e: "Early stopping based on intermediate trial performance (supported via Hyperopt's early_stop_fn or similar pruning mechanisms) avoids wasting compute on trials unlikely to improve on the best result so far, which is a key efficiency technique at scale.", t: "Scenario · Hard" },
    { q: "A team wants to serve a custom Python model with pre/post-processing logic (not just a raw scikit-learn model) as a single deployable unit with a consistent API.", o: ["Deploy the raw model object with no wrapping", "Wrap the model and its pre/post-processing logic in an MLflow pyfunc custom model (implementing a predict method), log it as a single artifact, and serve that", "Split pre-processing, model, and post-processing into three unrelated endpoints the client must call in order", "This requires abandoning MLflow entirely"], a: 1, e: "MLflow's pyfunc flavor lets you package arbitrary Python logic — including pre/post-processing wrapped around an underlying model — as a single custom model artifact with a consistent predict() interface, which can then be served as one endpoint.", t: "Scenario · Hard" },
    { q: "A Professional-level scenario requires that a batch scoring job only proceeds if the incoming scoring data's schema and key statistical properties match what the model was trained on, halting otherwise.", o: ["Always run batch scoring regardless of input validity", "Add automated data validation (schema checks and statistical checks, e.g., via Lakehouse Monitoring or custom expectations) before scoring, failing/alerting the job if the input diverges significantly from training-time expectations", "Manually eyeball a sample of the scoring data occasionally", "Retrain the model automatically on every scoring run instead of validating"], a: 1, e: "Gatekeeping batch scoring with automated schema and statistical validation (e.g., through Lakehouse Monitoring or explicit checks) prevents silently scoring on data that has drifted or changed shape from what the model expects — a key production ML reliability pattern.", t: "Scenario · Hard" },
    { q: "Multiple data scientists across teams need to discover, evaluate, and reuse a model logged by another team, along with its documented lineage and evaluation metrics, governed centrally.", o: ["Share model files informally over chat/email", "Register the model in the Unity Catalog-integrated Model Registry, where it gets a governed name, versioning, lineage, and access control that other teams can discover and reuse appropriately", "Keep each model private to its own workspace with no discovery mechanism", "Only communicate model existence verbally in meetings"], a: 1, e: "A centrally governed Model Registry (integrated with Unity Catalog) provides discoverability, versioning, lineage, and access control for models across teams — the standard, auditable way to share and reuse models at an organizational scale, rather than informal sharing.", t: "Scenario · Hard" },
    { q: "A production model's input feature distribution has shifted meaningfully from training, but the team must distinguish whether this is data drift (input distribution changed) or concept drift (the input-output relationship itself changed), since the fixes differ.", o: ["Both types of drift are identical and require the same fix", "Monitor input feature distributions separately from the model's residual/error patterns against ground truth once available — a shift in inputs alone suggests data drift, while degrading accuracy despite stable inputs suggests concept drift", "Only concept drift is worth monitoring in production", "Retrain on a fixed schedule regardless of which type of drift is occurring"], a: 1, e: "Distinguishing data drift (input distribution shift, potentially retrainable with fresh data using the same relationship) from concept drift (the underlying relationship between inputs and outputs has changed, requiring a fundamentally updated model or features) requires monitoring both input distributions and, once available, actual prediction accuracy — a key Professional-level MLOps distinction.", t: "Scenario · Medium" },
    { q: "A team building a recommendation system needs to prevent training data leakage where a user's future interactions accidentally appear as features predicting their past behavior.", o: ["Any historical feature is automatically leak-free", "Enforce point-in-time correctness in feature computation (e.g., using Feature Store's point-in-time lookups) so each training example only sees features as they existed at that example's timestamp, never future interactions", "Randomly shuffle all interactions before training", "Ignore timestamps entirely when joining features to training labels"], a: 1, e: "Point-in-time correct feature joins (a capability Feature Store provides) ensure each training row only sees feature values as of its own timestamp, preventing future information from leaking into training — a critical safeguard for recommendation and time-sensitive systems.", t: "Scenario · Medium" },
    { q: "A model deployment pipeline must support instant rollback to a previous model version if the newly deployed version causes a spike in errors or degraded business metrics.", o: ["Rely on manually retraining and redeploying a new model from scratch if something goes wrong", "Keep prior model versions registered and deployable in the Model Registry, and configure the serving endpoint/deployment process to support quickly re-pointing traffic to a known-good prior version", "Only test in staging and hope production never fails", "Delete old model versions immediately after each new deployment to save storage"], a: 1, e: "Retaining previous registered model versions and having a deployment process that can quickly re-point a serving endpoint to a known-good version is the standard safety net for production ML, enabling fast rollback instead of an emergency retrain-and-redeploy cycle.", t: "Scenario · Medium" },
    { q: "A Professional-level scenario requires securely serving a model that must never expose the raw underlying training data or feature values used, only the prediction, even to users with API access.", o: ["Expose full feature vectors alongside every prediction for transparency", "Design the serving endpoint's response schema to return only the prediction (and perhaps calibrated confidence), not raw internal features, and enforce this at the API/response-schema layer", "Let any API caller query the underlying feature tables directly", "There's no way to control what a serving endpoint returns"], a: 1, e: "Controlling a serving endpoint's response schema to expose only the prediction (not the underlying feature values used to compute it) is a straightforward but important security/privacy design decision enforced at the API contract layer.", t: "Scenario · Hard" },
    { q: "A team's automated retraining pipeline occasionally promotes a new model version that is technically 'better' on the offline metric but was trained on a data snapshot corrupted by an upstream bug, and this reaches production before anyone notices.", o: ["Fully automated retraining pipelines cannot be made safe", "Add data-quality validation gates (schema/statistical checks on the training data) before training even starts, and require the new model to also pass sanity/regression checks against known business rules before auto-promotion", "Disable all automation and revert to fully manual retraining forever", "Trust the offline metric alone as sufficient validation regardless of data quality"], a: 1, e: "Safe automated retraining pipelines validate input data quality before training and apply sanity/regression checks (beyond just the primary offline metric) before auto-promoting a new model version, catching cases where a corrupted data snapshot produces a technically-better-scoring but actually broken model.", t: "Scenario · Hard" },
    { q: "A multi-region deployment requires a model to be served with low latency in each region without duplicating the entire MLOps pipeline (training, registry, monitoring) per region.", o: ["Fully duplicate the entire pipeline independently in every region with no shared components", "Train and register the model centrally once, then deploy region-specific serving endpoints (or replicas) from that single registered model version, keeping training/registry centralized while serving is distributed for latency", "Only serve from a single region regardless of latency impact", "Retrain a completely separate model per region using only that region's own data with no coordination"], a: 1, e: "A common Professional-level pattern centralizes training, registration, and governance (single source of truth) while distributing only the serving layer (regional endpoints/replicas of the same registered model version) to meet regional latency requirements without duplicating the full MLOps pipeline.", t: "Scenario · Hard" },
    { q: "A team must decide whether a newly observed model performance drop is due to a code bug in the serving pipeline or genuine model/data drift, since the response differs (hotfix vs. retrain).", o: ["Always assume it's model drift and retrain immediately", "Systematically rule out pipeline/code issues first (comparing serving-time feature computation against training-time logic, checking for schema mismatches or bugs), then investigate data/concept drift if the pipeline itself is confirmed correct", "Always assume it's a code bug and never consider drift", "Ignore the drop until it becomes severe enough to be undeniable"], a: 1, e: "Professional-level incident response for model performance drops follows a systematic elimination process — first verifying the serving pipeline's correctness (feature parity with training, schema, bugs) before attributing the cause to drift — since the appropriate fix (hotfix vs. retrain) depends entirely on the true root cause.", t: "Scenario · Hard" },
    { q: "A model governance policy requires that any model touching regulated financial data be explainable to auditors, but the current champion model is a complex ensemble with no built-in interpretability.", o: ["Explainability cannot be added after the fact; the model must be scrapped", "Apply post-hoc explainability techniques (e.g., SHAP values) to approximate feature contributions for individual predictions, logging these explanations alongside predictions for audit purposes", "Only document the model's overall accuracy and skip per-prediction explanations", "Replace all complex models with a single global average regardless of performance loss"], a: 1, e: "Post-hoc explainability methods like SHAP can generate per-prediction feature attribution for otherwise complex/black-box models, and logging these explanations alongside predictions is a standard way to satisfy auditor/regulatory explainability requirements without necessarily sacrificing model performance.", t: "Scenario · Hard" },
    { q: "A CI/CD pipeline for ML must run automated tests not just on code, but also validate that a newly trained model's key slices (e.g., specific customer segments) don't perform substantially worse than the previous version, to catch fairness/regression issues before deployment.", o: ["Only test overall aggregate accuracy before deployment", "Include slice-based evaluation in the CI/CD pipeline, comparing the new model's performance on important subgroups/segments against the previous version and failing the pipeline if a critical slice regresses significantly", "Skip subgroup analysis since aggregate metrics are sufficient", "Only check subgroup performance manually after the model is already in production"], a: 1, e: "Slice-based evaluation as part of automated CI/CD — checking that important subgroups don't regress even if the aggregate metric looks fine — catches fairness and segment-specific regressions before deployment, which aggregate-only metrics can mask entirely.", t: "Scenario · Hard" },
    { q: "A regulated deployment requires that every automated retraining and promotion event be logged with who/what approved it, even though the pipeline runs unattended on a schedule.", o: ["Unattended pipelines can't be audited, so skip this requirement", "Log each pipeline run's data version, code version, evaluation results, and the automated/manual approval decision (e.g., via MLflow run metadata and registry stage-transition comments) to create a full audit trail even for unattended runs", "Only log successful promotions, skipping rejected ones", "Rely on the scheduler's own generic run logs as sufficient audit evidence"], a: 1, e: "A full audit trail — data/code versions, evaluation results, and the (automated or human) approval decision for each stage transition, captured via MLflow tracking and registry metadata — satisfies regulatory audit requirements even for unattended, scheduled pipelines, which generic scheduler logs alone would not.", t: "Scenario · Hard" },
  ],
};
